<?php
if(!defined('SCHOOLOS_OPERATIONS_LIBRARY')){header('Location: index.php?s=operations&area=hr',true,302);exit;}
function hr_schema():array{return [
 "CREATE TABLE IF NOT EXISTS hr_departments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,UNIQUE KEY department_name(tenant_id,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS hr_employees(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,staff_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,department_id BIGINT UNSIGNED NULL,status VARCHAR(20) NOT NULL DEFAULT 'onboarding',join_on DATE NOT NULL,basic_kobo BIGINT NOT NULL DEFAULT 0,UNIQUE KEY staff_once(tenant_id,staff_id),UNIQUE KEY employee_account(tenant_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS hr_recruitment(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,position VARCHAR(180) NOT NULL,applicant VARCHAR(180) NOT NULL,email VARCHAR(190) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'applied',notes TEXT NULL,employee_id BIGINT UNSIGNED NULL,INDEX(tenant_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS hr_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(20) NOT NULL,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',starts_at DATETIME NULL,ends_at DATETIME NULL,filename VARCHAR(180) NULL,filemime VARCHAR(100) NULL,filedata MEDIUMBLOB NULL,created_by BIGINT UNSIGNED NOT NULL,reviewed_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,employee_id,kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS hr_policy(tenant_id BIGINT UNSIGNED PRIMARY KEY,employee_bps INT NOT NULL,employer_bps INT NOT NULL,relief_kobo BIGINT NOT NULL,bands_json TEXT NOT NULL,pension_deductible TINYINT NOT NULL DEFAULT 1,reviewed_by BIGINT UNSIGNED NOT NULL,reviewed_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS hr_allowances(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,title VARCHAR(120) NOT NULL,amount_kobo BIGINT NOT NULL,taxable TINYINT NOT NULL DEFAULT 1,pensionable TINYINT NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1,INDEX(tenant_id,employee_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS hr_advances(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,amount_kobo BIGINT NOT NULL,monthly_kobo BIGINT NOT NULL,repaid_kobo BIGINT NOT NULL DEFAULT 0,reason VARCHAR(1000) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'requested',requested_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NULL,payment_ref VARCHAR(120) NULL,INDEX(tenant_id,employee_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS hr_payruns(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,period VARCHAR(7) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NULL,paid_by BIGINT UNSIGNED NULL,payment_ref VARCHAR(120) NULL,policy_json TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY payroll_period(tenant_id,period)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS hr_paylines(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,run_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,basic_kobo BIGINT NOT NULL,allowances_kobo BIGINT NOT NULL,gross_kobo BIGINT NOT NULL,paye_kobo BIGINT NOT NULL,pension_kobo BIGINT NOT NULL,employer_pension_kobo BIGINT NOT NULL,advance_kobo BIGINT NOT NULL,net_kobo BIGINT NOT NULL,calculation_json TEXT NOT NULL,UNIQUE KEY employee_period(run_id,employee_id),INDEX(tenant_id,employee_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS hr_repayments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,run_id BIGINT UNSIGNED NOT NULL,advance_id BIGINT UNSIGNED NOT NULL,amount_kobo BIGINT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'reserved',UNIQUE KEY repay_once(run_id,advance_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];}
function hr_bands(string $json):array{$rows=json_decode($json,true,64,JSON_THROW_ON_ERROR);if(!is_array($rows)||!array_is_list($rows)||!$rows||count($rows)>12)throw new RuntimeException('Use 1–12 tax bands.');$out=[];foreach($rows as $i=>$r){if(!is_array($r)||!array_key_exists('width_naira',$r)||!isset($r['rate_percent']))throw new RuntimeException('Bands require width_naira and rate_percent.');$width=$r['width_naira']===null?null:op_money((string)$r['width_naira']);if(($width===null)!==($i===count($rows)-1))throw new RuntimeException('Only the last band must have a null/unlimited width.');$out[]=['width_kobo'=>$width,'rate_bps'=>op_bps((string)$r['rate_percent'])];}return $out;}
function hr_calculate(int $basic,array $allowances,array $policy):array{
 if($basic<=0)throw new RuntimeException('Set a positive basic salary before payroll.');$total=0;$taxable=$basic;$pensionable=$basic;
 foreach($allowances as $a){$amt=(int)$a['amount_kobo'];if($amt<0)throw new RuntimeException('Invalid allowance.');$total+=$amt;if($a['taxable'])$taxable+=$amt;if($a['pensionable'])$pensionable+=$amt;}
 $pension=op_percent($pensionable,(int)$policy['employee_bps']);$employer=op_percent($pensionable,(int)$policy['employer_bps']);$annual=max(0,($taxable-($policy['pension_deductible']?$pension:0))*12-(int)$policy['relief_kobo']);$left=$annual;$tax=0;
 foreach(json_decode($policy['bands_json'],true,64,JSON_THROW_ON_ERROR) as $band){$slice=$band['width_kobo']===null?$left:min($left,(int)$band['width_kobo']);$tax+=op_percent($slice,(int)$band['rate_bps']);$left-=$slice;if(!$left)break;}
 $monthly=intdiv($tax+6,12);$gross=$basic+$total;if($pension+$monthly>$gross)throw new RuntimeException('Configured deductions exceed gross pay.');return ['basic'=>$basic,'allowances'=>$total,'gross'=>$gross,'paye'=>$monthly,'pension'=>$pension,'employer_pension'=>$employer,'annual_taxable'=>$annual,'annual_tax'=>$tax,'available'=>$gross-$monthly-$pension];
}
function hr_generate(array $u,string $period):int{
 global $pdo;op_need($u,'hr_manager');if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/D',$period))throw new RuntimeException('Use payroll month YYYY-MM.');$tid=(int)$u['tenant_id'];$pdo->beginTransaction();try{
  $policy=q('SELECT * FROM hr_policy WHERE tenant_id=? FOR UPDATE',[$tid])->fetch();if(!$policy)throw new RuntimeException('Configure and review PAYE/pension rules first.');q('INSERT INTO hr_payruns(tenant_id,period,created_by,policy_json) VALUES(?,?,?,?)',[$tid,$period,$u['id'],json_encode($policy,JSON_THROW_ON_ERROR)]);$run=(int)$pdo->lastInsertId();$end=(new DateTimeImmutable($period.'-01'))->modify('last day of this month')->format('Y-m-d');
  $employees=q("SELECT * FROM hr_employees WHERE tenant_id=? AND status IN ('active','exiting') AND join_on<=? ORDER BY id FOR UPDATE",[$tid,$end])->fetchAll();if(!$employees)throw new RuntimeException('No active employees for this period.');
  foreach($employees as $e){$allowances=q('SELECT title,amount_kobo,taxable,pensionable FROM hr_allowances WHERE tenant_id=? AND employee_id=? AND active=1',[$tid,$e['id']])->fetchAll();$c=hr_calculate((int)$e['basic_kobo'],$allowances,$policy);$deduct=0;
   foreach(q("SELECT * FROM hr_advances WHERE tenant_id=? AND employee_id=? AND status='disbursed' ORDER BY id FOR UPDATE",[$tid,$e['id']])->fetchAll() as $advance){$reserved=(int)g("SELECT COALESCE(SUM(amount_kobo),0) FROM hr_repayments WHERE tenant_id=? AND advance_id=? AND status='reserved'",[$tid,$advance['id']]);$amt=min((int)$advance['monthly_kobo'],max(0,(int)$advance['amount_kobo']-(int)$advance['repaid_kobo']-$reserved),max(0,$c['available']-$deduct));if($amt>0){q('INSERT INTO hr_repayments(tenant_id,run_id,advance_id,amount_kobo) VALUES(?,?,?,?)',[$tid,$run,$advance['id'],$amt]);$deduct+=$amt;}}
   $c['allowance_items']=$allowances;$c['staff_name']=(string)g('SELECT name FROM staff WHERE tenant_id=? AND id=?',[$tid,$e['staff_id']]);q('INSERT INTO hr_paylines(tenant_id,run_id,employee_id,basic_kobo,allowances_kobo,gross_kobo,paye_kobo,pension_kobo,employer_pension_kobo,advance_kobo,net_kobo,calculation_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[$tid,$run,$e['id'],$c['basic'],$c['allowances'],$c['gross'],$c['paye'],$c['pension'],$c['employer_pension'],$deduct,$c['available']-$deduct,json_encode($c,JSON_THROW_ON_ERROR)]);
  }audit('hr.payroll.generated','payrun',(string)$run);$pdo->commit();return $run;
 }catch(Throwable $e){$pdo->rollBack();throw $e;}
}
function hr_employee_for(array $u,int $id):array{$e=op_own('hr_employees',$u,$id);if(!op_can($u,'hr_manager')&&(int)$e['user_id']!==(int)$u['id'])throw new RuntimeException('Personnel record unavailable.');return $e;}
