 op_need($u,'hr_manager');
 if($a==='department'){q('INSERT INTO hr_departments(tenant_id,name) VALUES(?,?)',[$tid,op_text('name',120,true)]);return 'Department created.';}
 if($a==='employee'){
  $staff=op_own('staff',$u,op_id('staff_id'));$user=op_id('user_id');$dept=op_id('department_id');if($dept)op_own('hr_departments',$u,$dept);if($user){$account=op_own('users',$u,$user);if(!in_array($account['role'],['staff','teacher','school_admin'],true))throw new RuntimeException('Bind only a school employee account.');}
  q('INSERT INTO hr_employees(tenant_id,staff_id,user_id,department_id,join_on,basic_kobo) VALUES(?,?,?,?,?,?)',[$tid,$staff['id'],$user?:null,$dept?:null,op_date(op_text('join_on',10,true)),op_money(op_text('salary',20,true))]);return 'Existing staff record linked to HR. Complete onboarding before activation.';
 }
 if($a==='staff'){q('INSERT INTO staff(tenant_id,name,department,role_title) VALUES(?,?,?,?)',[$tid,op_text('name',180,true),op_text('department',120),op_text('role_title',120,true)]);return 'Staff record created. Link it to HR and an account explicitly.';}
 if($a==='recruit'){ $email=op_text('email',190,true);if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Valid applicant email required.');q('INSERT INTO hr_recruitment(tenant_id,position,applicant,email,notes) VALUES(?,?,?,?,?)',[$tid,op_text('position',180,true),op_text('applicant',180,true),$email,op_text('notes',3000)]);return 'Applicant saved in the private recruitment pipeline.';}
 if($a==='recruit_stage'){
  $id=op_id('application_id');$next=op_text('status',20);$pdo->beginTransaction();try{$r=q('SELECT * FROM hr_recruitment WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$id])->fetch();$trans=['applied'=>['shortlisted','rejected'],'shortlisted'=>['offered','rejected'],'offered'=>['hired','rejected']];if(!$r||!in_array($next,$trans[$r['status']]??[],true))throw new RuntimeException('Invalid recruitment transition.');$eid=null;if($next==='hired'){q('INSERT INTO staff(tenant_id,name,role_title) VALUES(?,?,?)',[$tid,$r['applicant'],$r['position']]);$sid=(int)$pdo->lastInsertId();q('INSERT INTO hr_employees(tenant_id,staff_id,join_on) VALUES(?,?,?)',[$tid,$sid,date('Y-m-d')]);$eid=(int)$pdo->lastInsertId();}q('UPDATE hr_recruitment SET status=?,employee_id=COALESCE(?,employee_id) WHERE tenant_id=? AND id=?',[$next,$eid,$tid,$id]);$pdo->commit();return 'Recruitment stage updated; hired applicants enter onboarding without automatic login credentials.';}catch(Throwable $ex){$pdo->rollBack();throw $ex;}
