 if($a==='salary'){$e=op_own('hr_employees',$u,op_id('employee_id'));$amt=op_money(op_text('salary',20,true));q('UPDATE hr_employees SET basic_kobo=? WHERE tenant_id=? AND id=?',[$amt,$tid,$e['id']]);audit('hr.salary.updated','employee',(string)$e['id']);return 'Basic salary changed for future runs; existing payslips are immutable.';}
