function hr_file(array $u,int $id):void{$r=op_own('hr_items',$u,$id);$e=hr_employee_for($u,(int)$r['employee_id']);if(!op_can($u,'hr_manager')&&($r['kind']==='evaluation'&&$r['status']!=='published'))throw new RuntimeException('Document unavailable.');if($r['filedata']===null)throw new RuntimeException('No document attached.');header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.preg_replace('/[^A-Za-z0-9._-]/','_',$r['filename']).'"');header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');echo $r['filedata'];exit;}
